import zlib
import json

# Your hex string (truncated for brevity in this example)
hex_data = ""

# 1. Convert hex to bytes
binary_data = bytes.fromhex(hex_data)

# 2. Decompress using zlib
decompressed_data = zlib.decompress(binary_data)

# 3. Decode to string and 4. Parse as JSON
json_obj = json.loads(decompressed_data.decode("utf-8"))

print(json.dumps(json_obj, indent=2))
